function validate([s, t, k]) {
  for (const [name, str] of [['s', s], ['t', t]]) {
    if (typeof str !== 'string' || str.length < 1 || str.length > 100000) return `${name} needs 1 to 100000 letters.`;
    if (!/^[a-z]+$/.test(str)) return `${name} uses only lowercase English letters.`;
  }
  if (!Number.isInteger(k) || k < 0 || k > 1000000000) return 'k is an integer from 0 to 10^9.';
  return null;
}

