    const shift = (t.charCodeAt(i) - s.charCodeAt(i) + 26) % 26;
    if (shift === 0) {
      continue;
    }
    const move = shift + 26 * count[shift];
    if (move > k) {
      return false;
    }
    count[shift]++;
  }
