function canConvertString(s, t, k) {
  // Simulate: give each position the smallest unused move that shifts its letter correctly.
  if (s.length !== t.length) return false;
  const used = new Set();
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  for (let p = 0; p < s.length; p++) {
    if (s[p] === t[p]) continue;
    let move = 1;
    while (used.has(move) || letters[(letters.indexOf(s[p]) + move) % 26] !== t[p]) move++;
    if (move > k) return false;
    used.add(move);
  }
  return true;
}

