function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(6000, 10000) : int(1, 8);
  const alphabet = large ? 26 : (rand() < 0.5 ? 3 : 26);
  const letter = () => String.fromCharCode(97 + int(0, alphabet - 1));
  const same = rand() * 0.8;
  let s = '', t = '';
  for (let i = 0; i < n; i++) {
    const ch = letter();
    s += ch;
    t += rand() < same ? ch : letter();
  }
  if (!large && rand() < 0.12) t = t.length > 1 && rand() < 0.5 ? t.slice(1) : t + letter();
  // The smallest k that works decides the answer; pick k at, just below or away from it.
  const count = new Array(26).fill(0);
  let need = 0;
  for (let i = 0; i < Math.min(s.length, t.length); i++) {
    const shift = (t.charCodeAt(i) - s.charCodeAt(i) + 26) % 26;
    if (shift) need = Math.max(need, shift + 26 * count[shift]++);
  }
  const r = rand();
  const k = r < 0.35 ? need : r < 0.7 ? Math.max(0, need - int(1, 3)) : r < 0.85 ? int(0, large ? 1000000000 : 60) : need + int(0, 30);
  return [s, t, k];
}
